import{_ as t,o,c as d,a0 as a}from"./chunks/framework.l1I-fhud.js";const m=JSON.parse('{"title":"Content types","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/content-types.md","filePath":"explanation/content-types.md"}'),n={name:"explanation/content-types.md"};function r(s,e,i,c,l,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="content-types" tabindex="-1">Content types <a class="header-anchor" href="#content-types" aria-label="Permalink to &quot;Content types&quot;">​</a></h1><p>The engine is <strong>generic</strong>: it moves <em>bytes + a manifest</em> and doesn&#39;t care what the bytes mean. A <strong>content type</strong> declares the meaning — where and how a package installs.</p><h2 id="declared-not-linked" tabindex="-1">Declared, not linked <a class="header-anchor" href="#declared-not-linked" aria-label="Permalink to &quot;Declared, not linked&quot;">​</a></h2><p>A content type is <em>data first</em>: the package&#39;s manifest names its <code>type</code> (<code>kind</code>). The manager never links a product crate. When a product must do real work (materialize a node config, enable a systemd unit), it ships a <strong>driver</strong> binary the manager launches over a pipe — &quot;no plugin system: files&quot; (peregrin’s own ADR).</p><h2 id="the-roster" tabindex="-1">The roster <a class="header-anchor" href="#the-roster" aria-label="Permalink to &quot;The roster&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Payload</th><th>Installs into</th></tr></thead><tbody><tr><td><code>peregrin-bundle</code></td><td>workflows, <code>.node.yml</code>, <code>.snippet.yml</code>, <code>.field.yml</code>, <code>.prompt.yml</code></td><td>the peregrin bundle store</td></tr><tr><td><code>myco-config</code></td><td><code>[[kinds]]</code>, <code>[views]</code>, <code>[verbs]</code>, templates</td><td><code>myco.toml</code> / a seeded <code>project/</code></td></tr><tr><td><code>kuda-domain</code></td><td><code>data/domains/*.toml</code></td><td><code>.kuda/domains/</code></td></tr><tr><td><code>mimus-rules</code></td><td><code>rules/*.toml</code></td><td><code>rules/</code></td></tr><tr><td><code>files</code></td><td>anything</td><td>the store entry (no driver)</td></tr></tbody></table><p>Adding a type is a new <code>tamias-driver-&lt;type&gt;</code> binary — never a change to the engine.</p><h2 id="providers-and-the-driver-system" tabindex="-1">Providers (and the driver system) <a class="header-anchor" href="#providers-and-the-driver-system" aria-label="Permalink to &quot;Providers (and the driver system)&quot;">​</a></h2><p>The engine is generic — it moves <em>bytes + a manifest</em> and unpacks into the store. Everything product-specific beyond that is a <strong>provider</strong>: tamias shells <code>&lt;provider&gt; provision {install,deploy,uninstall} --dir … --name … [--config …]</code> and never learns the product&#39;s schema.</p><ul><li><code>peregrin-bundle</code> → provider <strong><code>peregrin</code></strong> (materializes a node config + a systemd unit).</li><li><code>files</code> → no provider (the store install is the whole story).</li></ul><p>This is generalizing into a first-class <strong>driver system</strong> (<code>P10</code>): each product ships a Rust binary <strong><code>tamias-driver-&lt;name&gt;</code></strong>, tamias discovers it on <code>PATH</code>/<code>&lt;tamias-home&gt;/drivers/</code>, and speaks JSON over stdio (<code>capabilities</code>/<code>install</code>/<code>deploy</code>/<code>uninstall</code>). Installing a product drops its driver; tamias finds it. No compile-time coupling either way.</p>',11)])])}const g=t(n,[["render",r]]);export{m as __pageData,g as default};
